const St = imports.gi.St;

const {QVisualizer, clamp01, parse_color} = require("js/QVisualizer.js");
const {get_effect_class} = require("js/QAdvancedEffect.js");
const QUtils = require("js/QUtils.js");
const {qLOG} = QUtils;

// GPU-only visualizer: the whole frame is generated by a fragment shader (no
// Cairo, no Clutter.Canvas). The smoothed spectrum is resampled to
// SPECTRUM_BINS and uploaded as a float array uniform.
const SPECTRUM_BINS = 64;

// Presets render at their natural aspect ratio (width : height); anything not
// listed here is square. advanced_size is the canvas width, so a landscape
// preset such as Sunset gets a 16:9 frame.
const PRESET_ASPECT = {
  sunset: 16 / 9
};

const ADVANCED_DEFAULTS = {
  size:         300,
  preset:       "fire_ring",
  bars:         64,
  shader_dir:   "",
  intensity:    1.0,
  speed:        1.0,
  frame:        0,
  color_from:   "rgba(204,40,149,0.8)",
  color_to:     "rgba(255,208,65,1)",
  accent_color: "rgba(255,255,255,0.2)"
};

class QAdvancedVisualizer extends QVisualizer {

  constructor(opts) {
    super(Object.assign({}, ADVANCED_DEFAULTS, opts || {}));
    this._preset = this.opts.preset;
  }

  _canvas_size() {
    const w = Math.max(100, this.opts.size || 300);
    const key = String(this.opts.preset || "fire_ring").replace(/-/g, "_");
    const aspect = PRESET_ASPECT[key] || 1.0;
    return [w, Math.max(1, Math.round(w / aspect))];
  }

  // The shader animates continuously (u_time), even when the audio is silent.
  _animate(dt) {
    return true;
  }

  _build_surface() {
    this._effect = null;
    this._spectrum = new Array(SPECTRUM_BINS).fill(0);
    const size = this._canvas_size();
    this.actor = new St.Widget({width: size[0], height: size[1], reactive: false});
    // A near-transparent but non-empty background keeps Clutter from culling
    // the actor; the shader ignores the actor's own texture anyway.
    this.actor.set_style("background-color: rgba(0,0,0,0.004);");
    this._build_effect();
  }

  _build_effect() {
    const preset = this.opts.preset || "fire_ring";
    if (this._effect && this.actor) {
      try { this.actor.remove_effect(this._effect); } catch (e) { /* gone */ }
      this._effect = null;
    }
    const Klass = get_effect_class(preset, this.opts.shader_dir);
    if (!Klass) {
      qLOG.e("QAdvancedVisualizer: no effect class for preset", preset);
      return;
    }
    this._effect = new Klass();
    this.actor.add_effect_with_name("qadvanced", this._effect);
    this._push_uniforms();
  }

  // Resample the smoothed bands (length = bars) to SPECTRUM_BINS with linear
  // interpolation so the shader always sees a fixed-size array.
  _update_spectrum() {
    const out = this._spectrum;
    const d = this._disp;
    const n = d.length;
    if (n === 0) return out;
    for (let i = 0; i < SPECTRUM_BINS; i++) {
      const f = (i / (SPECTRUM_BINS - 1)) * (n - 1);
      const i0 = Math.floor(f);
      const i1 = Math.min(n - 1, i0 + 1);
      const t = f - i0;
      out[i] = clamp01(d[i0] * (1 - t) + d[i1] * t);
    }
    return out;
  }

  // Scalar band stats driving the presets: overall level, bass, treble.
  _stats() {
    const d = this._disp;
    const n = d.length;
    if (n === 0) return {level: 0, bass: 0, treble: 0};
    let sum = 0;
    for (let i = 0; i < n; i++) sum += d[i];
    const nb = Math.max(1, Math.floor(n * 0.12));
    const nt = Math.max(1, Math.floor(n * 0.25));
    let bs = 0;
    for (let i = 0; i < nb; i++) bs += d[i];
    let ts = 0;
    for (let i = n - nt; i < n; i++) ts += d[i];
    return {level: sum / n, bass: bs / nb, treble: ts / nt};
  }

  // Onset envelope for the presets: fast attack on a bass rise above its slow
  // average, then an exponential decay. Half-wave rectified energy rise, as in
  // QRingVisualizer. https://en.wikipedia.org/wiki/Onset_(audio)
  _beat_envelope(bass, dt) {
    if (this._bass_slow === undefined) {
      this._bass_slow = bass;
      this._beat = 0;
    }
    const slow = 1 - Math.exp(-dt / 1.2);
    this._bass_slow += (bass - this._bass_slow) * slow;
    const onset = Math.max(0, bass - this._bass_slow);
    const decay = Math.exp(-dt / 0.22);
    this._beat = Math.max(this._beat * decay, clamp01(onset * 5.0));
    return this._beat;
  }

  _push_uniforms() {
    if (!this._effect) return;
    // Use the actor's real size: St may allocate it slightly differently from
    // the requested one, and the shader's frame mask works in pixels.
    const want = this._canvas_size();
    const aw = (this.actor && this.actor.width > 0) ? this.actor.width : want[0];
    const ah = (this.actor && this.actor.height > 0) ? this.actor.height : want[1];
    const cfrom = parse_color(this.opts.color_from);
    const cto = parse_color(this.opts.color_to);
    const cacc = parse_color(this.opts.accent_color);
    const st = this._stats();
    const beat = this._beat_envelope(st.bass, this._dt_s || (1 / 60));
    this._effect.set_uniforms({
      time:       this._time,
      intensity:  this.opts.intensity,
      speed:      this.opts.speed,
      bars:       this.opts.bars,
      level:      st.level,
      centroid:   this._centroid,
      bass:       st.bass,
      treble:     st.treble,
      beat:       beat,
      frame:      this.opts.frame,
      width:      aw,
      height:     ah,
      color_from: [cfrom[0], cfrom[1], cfrom[2]],
      color_to:   [cto[0], cto[1], cto[2]],
      accent:     [cacc[0], cacc[1], cacc[2]]
    });
  }

  _present() {
    if (!this._effect) return;
    this._effect.set_spectrum(this._update_spectrum());
    this._push_uniforms();
    this._effect.queue_repaint();
  }

  _resize_surface(w, h) {
    if (this.actor) this.actor.set_size(w, h);
  }

  set_preset(preset) {
    if (!preset || preset === this._preset) return;
    this._preset = preset;
    this.opts.preset = preset;
    // Presets can differ in aspect ratio (e.g. Sunset is 16:9), so resize.
    const size = this._canvas_size();
    if (this.actor) this.actor.set_size(size[0], size[1]);
    // Rebuild the chain so the advanced effect stays under the shade effect
    // (Clutter applies effects in add order).
    if (this._shades && this.actor) {
      try { this.actor.remove_effect(this._shades); } catch (e) { /* gone */ }
      this._shades = null;
    }
    this._build_effect();
    this._sync_shades();
    this._present();
  }

  destroy() {
    if (this._effect && this.actor) {
      try { this.actor.remove_effect(this._effect); } catch (e) { /* gone */ }
    }
    this._effect = null;
    this._spectrum = null;
    super.destroy();
  }
}

module.exports = {
  QAdvancedVisualizer
};
